#!/usr/bin/env bash
# 療育カリキュラム管理 v2.4 / 既存Dockerの療育アプリのみを更新
# アプリZIPを内蔵。実際の児童情報・設定秘密鍵は含めない。
set -Eeuo pipefail
umask 077
EXPECTED_SHA256="c72ddb97ea4a8b5d999a0a1dbd999f337d59bb27d9207d233d91539550ab97fa"
usage() {
cat <<'HELP'
使い方：
  bash update-ryoiku-v2.4.sh --verify        # 更新ファイルの整合性確認（sudo不要）
  sudo bash update-ryoiku-v2.4.sh --check    # 導入先とDockerを確認する（変更なし）
  sudo bash update-ryoiku-v2.4.sh --apply    # データバックアップ → Dockerの再ビルド・起動

v2.3以降の既存アプリ専用。新規インストール用ではありません。
既存の3000番サービス・Tailscale Serve設定・データ・暗号化キーは変更しません。
HELP
}
fail(){ printf 'エラー: %s\n' "$*" >&2; exit 1; }
mode="${1:---check}"
case "$mode" in
  --help|-h) usage;exit 0;;
  --verify|--check|--apply) ;;
  *) usage >&2;exit 2;;
esac
for c in base64 sha256sum unzip mktemp tar; do
  command -v "$c" >/dev/null 2>&1 || fail "$c がありません。Ubuntuなら sudo apt install unzip などで準備してください。"
done
TMP="$(mktemp -d)"
cleanup(){ rm -rf "$TMP"; }
trap cleanup EXIT
base64 -d >"$TMP/app.zip" <<'RYOIKU_B64'
