RYOIKU_B64
actual="$(sha256sum "$TMP/app.zip" | awk '{print $1}')"
[[ "$actual" == "$EXPECTED_SHA256" ]] || fail '更新用ZIPのチェックサムが一致しません。'
unzip -tqq "$TMP/app.zip" || fail '更新ZIPが壊れています。'
if [[ "$mode" == '--verify' ]]; then
  printf 'OK: v2.4 内蔵ZIPの検証に成功 (SHA256=%s)\n' "$actual"
  exit 0
fi
[[ "$EUID" -eq 0 ]] || fail 'Docker操作にはsudoが必要です。'
for c in docker curl; do command -v "$c" >/dev/null 2>&1 || fail "$c がありません。"; done
docker compose version >/dev/null || fail 'Docker Composeが使えません。'
docker info >/dev/null || fail 'Dockerに接続できません。'
container='minecraft-ryoiku-web'
docker container inspect "$container" >/dev/null 2>&1 || fail "${container} が見つかりません。docker ps -a を確認してください。"
service="$(docker inspect -f '{{ index .Config.Labels "com.docker.compose.service" }}' "$container")"
[[ "$service" == 'ryoiku' ]] || fail "想定外のDocker Composeサービス名です: ${service}"
DEST="$(docker inspect -f '{{ index .Config.Labels "com.docker.compose.project.working_dir" }}' "$container")"
[[ -n "$DEST" && "$DEST" != '<no value>' && "$DEST" == /* && -d "$DEST" ]] || fail 'インストール先が検出できません。'
[[ -f "$DEST/compose.yml" && -f "$DEST/.env" && -d "$DEST/data" ]] || fail 'compose.yml/.env/dataの存在を確認できません。'
printf '\nDocker: %s\n実際のインストール先: %s\n' "$container" "$DEST"
docker compose -f "$DEST/compose.yml" --project-directory "$DEST" ps ryoiku
if [[ "$mode" == '--check' ]]; then
  echo '事前確認のみ完了：ファイルとDocker設定は変更していません。'
  exit 0
fi
unzip -q "$TMP/app.zip" -d "$TMP"
SOURCE="$TMP/minecraft_ryoiku_web"
for f in app.py storage.py ai.py providers.py templates/settings.html compose.yml Dockerfile; do
  [[ -f "$SOURCE/$f" ]] || fail "更新に必要なファイルがありません: $f"
done
[[ ! -e "$SOURCE/.env" && ! -e "$SOURCE/data" ]] || fail 'ZIPに個人データが含まれます。中止します。'
# カスタマイズされたComposeファイルを勝手に上書きしない。
if ! cmp -s "$SOURCE/compose.yml" "$DEST/compose.yml"; then
  fail '現在のcompose.ymlにカスタマイズがあります。自動上書きは停止しました。'
fi
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/var/backups/ryoiku-curriculum/${STAMP}"
mkdir -p "$BACKUP"
chmod 700 /var/backups/ryoiku-curriculum "$BACKUP"
cd "$DEST"
echo '療育コンテナだけを停止します（他のDockerサービスには触れません）。'
docker compose stop ryoiku
echo '個人データと設定をバックアップします。'
tar -czf "$BACKUP/data-and-env.tar.gz" .env data || fail 'バックアップに失敗しました。原因を確認するまで再実行しないでください。'
tar --exclude='./data' --exclude='./.env' -czf "$BACKUP/code-before-update.tar.gz" . || fail '旧コードのバックアップに失敗しました。'
chmod 600 "$BACKUP"/*.gz
# .envとdata/は絶対に上書きしない。
cp -a "$SOURCE/." "$DEST/"
echo '療育アプリv2.4をビルドします。'
docker compose build ryoiku
docker compose up -d --no-deps ryoiku
success=0
for _ in $(seq 1 20); do
  status="$(curl -sS -o /dev/null -w '%{http_code}' --max-time 3 http://127.0.0.1:8080/login || true)"
  if [[ "$status" == '200' || "$status" == '303' ]]; then success=1;break; fi
  sleep 2
done
docker compose ps ryoiku
if [[ "$success" != 1 ]]; then
  printf '\n起動は試行しましたが、HTTP応答を確認できませんでした。\n'
  printf 'バックアップ: %s\n' "$BACKUP"
  printf 'ログの確認: cd "%s" && sudo docker compose logs --tail=100 ryoiku\n' "$DEST"
  exit 3
fi
printf '\nOK: v2.4更新完了。Tailscaleと既存3000番には変更なし。\n'
printf 'インストール先: %s\nバックアップ: %s\n' "$DEST" "$BACKUP"
printf '管理者でWebUI →「AI設定」からClaude・Gemini等を選択してください。\n'
